scenario.en:
const { result } = renderHook(() => useCounter());
const snapshot = result.current;       // { count: 0, increment }

act(() => { result.current.increment(); });

expect(result.current.count).toBe(1);  // assertion A
expect(snapshot.count).toBe(1);        // assertion B

